import { useState, useEffect } from 'react';
import { useMapStore } from '../store/useMapStore';
import { FiRefreshCw, FiDownload, FiUpload } from 'react-icons/fi';
import { CATEGORY_MAP, determineParentLocation } from '../config/categories';
import { fetchAndMergeSheetUpdates, repairSheet1Headers, overwriteSheetWithFeatures, overwriteAreasSheet, overwriteLandmarksSheet } from '../services/googleSheets';
import toast from 'react-hot-toast';

const DEFAULT_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbz-uODChErEEwzVQOeQUefR-Q0yhsOWFHxolbpxmSTu4SyVl_0Hpec-mG2kgIZH7-A/exec';

export default function GoogleSheetsConnect() {
  const [isUpdatingMap, setIsUpdatingMap] = useState(false);
  const [isUpdatingSheet, setIsUpdatingSheet] = useState(false);
  const theme = useMapStore(state => state.theme);
  const spreadsheetId = useMapStore(state => state.spreadsheetId);
  const isDark = theme === 'dark';

  // ─── Update Map (Sheet → Map) ────────────────────────────────────────────────
  const updateMap = async (silent = false) => {
    if (!silent) setIsUpdatingMap(true);
    let toastId = null;

    if (!silent) {
      toastId = toast.loading('Loading polygons...', { id: 'loading-polygons' });
    }

    try {
      if (spreadsheetId) {
        await repairSheet1Headers(spreadsheetId);
      }
      await fetchAndMergeSheetUpdates(spreadsheetId);

      if (toastId) {
        toast.dismiss(toastId);
      }
    } catch (err) {
      console.error(err);
      if (!silent) {
        toast.error('Failed to connect: ' + err.message, { id: toastId || 'error-polygons' });
      }
    }
    if (!silent) setIsUpdatingMap(false);
  };

  // ─── 10-Second Background Polling (Sheet → Map) ────────────────────────────
  useEffect(() => {
    // Only poll if we have a spreadsheet ID
    if (!spreadsheetId) return;

    const intervalId = setInterval(() => {
      // Call updateMap silently so it doesn't spam toasts or loading spinners
      updateMap(true);
    }, 10000); // 10 seconds

    return () => clearInterval(intervalId);
  }, [spreadsheetId]);
  // ─── Global Event Listener for Update Sheet ─────────────────────────────────
  useEffect(() => {
    const handleGlobalUpdateSheet = () => {
      console.log('[Global Event] Triggering Update Sheet...');
      updateSheet();
    };

    window.addEventListener('trigger-update-sheet', handleGlobalUpdateSheet);
    return () => window.removeEventListener('trigger-update-sheet', handleGlobalUpdateSheet);
  }, []);

  // ─── Update Sheet (Map → Sheet) ──────────────────────────────────────────────
  const updateSheet = async () => {
    setIsUpdatingSheet(true);
    try {
      const currentFeatures = useMapStore.getState().features;
      const cleanFeatures = currentFeatures.map(f => {
        const d = f.data || {};
        const loc = d.location || f.location || '';
        const parentLoc = d.parentLocation || d.parent_location || f.parentLocation || determineParentLocation(loc) || '';
        const tpVal = d.tp || f.tp || '';
        const opVal = d.op || f.op || '';
        const fpVal = d.fp || f.fp || '';
        const areaVal = d.area != null ? d.area : (f.area != null ? f.area : '');
        const landmarkVal = d.landmark || f.landmark || '';
        const typeVal = d.type || '';
        const remarksVal = d.remarks || f.remarks || '';

        let partyNameVal = d.partyName || f.partyName || '';
        let partyPhoneVal = d.partyPhone || f.partyPhone || '';
        let brokerNameVal = d.brokerName || f.brokerName || '';
        let brokerPhoneVal = d.brokerPhone || f.brokerPhone || '';

        if (partyNameVal.includes('[{"lat":')) partyNameVal = '';
        if (partyPhoneVal.includes('[{"lat":')) partyPhoneVal = '';
        if (brokerNameVal.includes('[{"lat":')) brokerNameVal = '';
        if (brokerPhoneVal.includes('[{"lat":')) brokerPhoneVal = '';

        return {
          id: f.id,
          type: f.type,
          coordinates: f.coordinates || [],
          tp: tpVal,
          op: opVal,
          fp: fpVal,
          area: areaVal,
          location: loc,
          parentLocation: parentLoc,
          landmark: landmarkVal,
          category: typeVal,
          remarks: remarksVal,
          partyName: partyNameVal,
          partyPhone: partyPhoneVal,
          brokerName: brokerNameVal,
          brokerPhone: brokerPhoneVal,
          data: { tp: tpVal, op: opVal, fp: fpVal, area: areaVal, location: loc, parentLocation: parentLoc, landmark: landmarkVal, type: typeVal, remarks: remarksVal, partyName: partyNameVal, partyPhone: partyPhoneVal, brokerName: brokerNameVal, brokerPhone: brokerPhoneVal }
        };
      });

      const polygonFeatures = cleanFeatures.filter(cf => !(cf.id?.startsWith('landmark-') || cf.category === 'Landmark'));

      const headerRow = ['id', 'tp', 'op', 'fp', 'area', 'location', 'parent_location', 'landmark', 'type', 'remarks', 'Party Name', 'Party Phone', 'Broker Name', 'Broker Phone', 'coordinates'];
      const dataRows = polygonFeatures.map(cf => [
        cf.id || '', cf.tp || '', cf.op || '', cf.fp || '',
        cf.area != null ? String(cf.area) : '',
        cf.location || '', cf.parentLocation || '', cf.landmark || '',
        cf.category || '', cf.remarks || '',
        cf.partyName || '', cf.partyPhone || '', cf.brokerName || '', cf.brokerPhone || '',
        cf.coordinates && cf.coordinates.length > 0 ? JSON.stringify(cf.coordinates) : ''
      ]);
      const cleanRowsWithHeaders = [headerRow, ...dataRows];

      // Build areaRows
      const areaHeaders = ['Parent Location', 'Secondary Location', 'Polygon IDs'];
      const areaRows = [areaHeaders];
      const customAreas = useMapStore.getState().customAreas || [];
      const allParents = Array.from(new Set([...Object.keys(CATEGORY_MAP), ...customAreas]));
      allParents.forEach(parent => {
        const subs = CATEGORY_MAP[parent] || [];
        if (subs.length > 0) {
          subs.forEach(sub => {
            const matchedIds = polygonFeatures
              .filter(pf => pf.parentLocation === parent && pf.location === sub)
              .map(pf => pf.id)
              .filter(Boolean)
              .join(',');
            areaRows.push([parent, sub, matchedIds]);
          });
        } else {
          const matchedIds = polygonFeatures
            .filter(pf => pf.parentLocation === parent && (!pf.location || pf.location === parent))
            .map(pf => pf.id)
            .filter(Boolean)
            .join(',');
          areaRows.push([parent, '', matchedIds]);
        }
      });

      // Build landmark rows - ONLY include dedicated landmark pins
      const seenLandmarkNames = new Set();
      const landmarkRows = currentFeatures
        .filter(f => f.id?.startsWith('landmark-') || f.data?.type === 'Landmark')
        .map(f => {
          const d = f.data || {};
          const loc = d.location || 'Surat';
          const landmarkName = d.landmark || d.name || 'Landmark';

          return {
            id: f.id,
            landmarkName,
            loc,
            parentLoc: d.parentLocation || d.parent_location || determineParentLocation(loc),
            lat: f.position?.lat || f.center?.lat || '',
            lng: f.position?.lng || f.center?.lng || '',
            remarks: d.remarks || ''
          };
        })
        .filter(r => {
          if (!r.landmarkName || seenLandmarkNames.has(r.landmarkName.toLowerCase())) return false;
          seenLandmarkNames.add(r.landmarkName.toLowerCase());
          return true;
        })
        .map(r => [r.id, r.landmarkName, r.loc, r.parentLoc, r.lat, r.lng, r.remarks]);

      toast('Updating Google Sheets…');

      console.log('[UpdateSheet] landmarkRows count:', landmarkRows.length);
      console.log('[UpdateSheet] landmarkRows sample:', landmarkRows.slice(0, 2));
      console.log('[UpdateSheet] spreadsheetId:', spreadsheetId);

      // Direct Google Sheets API overwrite
      if (spreadsheetId) {
        try {
          const currentPolygons = currentFeatures.filter(f => !(f.id?.startsWith('landmark-') || f.data?.type === 'Landmark'));
          await overwriteSheetWithFeatures(spreadsheetId, currentPolygons);
          await overwriteAreasSheet(spreadsheetId, areaRows);
          console.log('[UpdateSheet] Calling overwriteLandmarksSheet with', landmarkRows.length, 'rows');
          await overwriteLandmarksSheet(spreadsheetId, landmarkRows);
          console.log('[UpdateSheet] overwriteLandmarksSheet done');
        } catch (err) {
          console.error('Direct Google Sheets API overwrite error:', err);
        }
      }

      // Apps Script webhook backup
      const landmarkHeaders = ['id', 'Landmark Name', 'Location', 'Parent Location', 'Latitude', 'Longitude', 'Remarks'];
      const landmarkRowsWithHeaders = [landmarkHeaders, ...landmarkRows];
      await fetch(DEFAULT_SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'sync', headers: headerRow, rows: cleanRowsWithHeaders, areaRows, landmarkRows: landmarkRowsWithHeaders, features: cleanFeatures })
      });

      toast.success(`Sheet updated! ${polygonFeatures.length} polygons & ${allParents.length} areas pushed to Google Sheets.`);
      useMapStore.setState({ googleSheetsConnected: true });

      const newSyncedAreas = areaRows.slice(1).map(row => ({ parent: row[0], secondary: row[1] || '' }));
      useMapStore.setState({ syncedAreas: newSyncedAreas });

      // Mark all features as synced
      const latestFeatures = useMapStore.getState().features;
      useMapStore.getState().setFeatures(latestFeatures.map(f => ({ ...f, syncStatus: 'synced' })));
    } catch (err) {
      console.error(err);
      toast.error('Failed to update Google Sheets: ' + err.message);
    }
    setIsUpdatingSheet(false);
  };

  // Wire "Save" button in PropertyInfoPanel to trigger updateSheet
  useEffect(() => {
    const handleGlobalSync = () => updateSheet();
    window.addEventListener('trigger-global-sync', handleGlobalSync);
    return () => window.removeEventListener('trigger-global-sync', handleGlobalSync);
  }, []); // Added empty dependency array for safety

  // Auto-load map from Google Sheets on startup to bypass any local storage reliance
  useEffect(() => {
    if (spreadsheetId) {
      useMapStore.getState().clearAllFeatures(); updateMap();
    }
  }, []); // Run once on mount

  return null;
}

import { useEffect, useRef, useCallback } from 'react';
import { useMapStore } from '../store/useMapStore';
import { useGoogleMap } from '../context/GoogleMapContext';

const geocodeCache = new Map();

// Helper to strip leading symbols/punctuation and guiding words like 'near', 'nr.', 'b/h', 'opp.', 'opposite', 'behind'
export function cleanLandmarkTitle(rawTitle) {
  if (!rawTitle || typeof rawTitle !== 'string') return '';
  let str = rawTitle.trim();

  // Strip leading non-alphanumeric noise (like "..", ", ", "- ", "_ ")
  str = str.replace(/^[^a-zA-Z0-9]+/, '').trim();

  // Pattern matching guiding prefix words
  const prefixRegex = /^(?:nr|near|b\/h|b\.h\.|bh|opp|opposite|adj|adjacent|behind|next\s+to)[\s\.,:-]+/i;

  let previous = '';
  while (str !== previous) {
    previous = str;
    str = str.replace(/^[^a-zA-Z0-9]+/, '').trim();
    str = str.replace(prefixRegex, '').trim();
  }

  // Strip trailing punctuation/noise
  str = str.replace(/^[^a-zA-Z0-9]+/, '').replace(/[\s\.,:-]+$/, '').trim();

  if (str.length > 0) {
    str = str.charAt(0).toUpperCase() + str.slice(1);
  }

  return str;
}

export async function resolveLandmarkLocation(landmark, fallbackCenter) {
  if (!landmark || !landmark.trim()) return null;
  const cleanLandmark = cleanLandmarkTitle(landmark);
  const cacheKey = cleanLandmark.toLowerCase();

  if (geocodeCache.has(cacheKey)) {
    return geocodeCache.get(cacheKey);
  }

  // 1. Search our built map first (local features)
  try {
    const features = useMapStore.getState().features || [];
    let bestMatch = null;

    for (const f of features) {
      const d = f.data || {};
      const possibleNames = [
        f.id,
        d.name,
        d.location,
        d.subLocation
      ].filter(Boolean);

      for (const name of possibleNames) {
        // Only check names that aren't generic auto-generated IDs
        if (typeof name === 'string' && name.startsWith('landmark-')) continue;

        const cleanName = cleanLandmarkTitle(name).toLowerCase();
        if (!cleanName) continue;

        if (cleanName === cacheKey || (cleanName.length > 3 && cacheKey.length > 3 && (cleanName.includes(cacheKey) || cacheKey.includes(cleanName)))) {
          bestMatch = f;
          break;
        }
      }
      if (bestMatch) break;
    }

    if (bestMatch) {
      const pos = bestMatch.center || bestMatch.position;
      if (pos) {

        geocodeCache.set(cacheKey, pos);
        return pos;
      }
    }
  } catch (err) {
    console.error("Error searching local features for landmark:", err);
  }

  // 2. Fallback to Google Maps Geocoder
  if (!window.google?.maps?.Geocoder) return null;

  const geocoder = new window.google.maps.Geocoder();

  let query = cleanLandmark;
  if (!cleanLandmark.toLowerCase().includes('surat') && !cleanLandmark.toLowerCase().includes('gujarat')) {
    query = `${cleanLandmark}, Surat, Gujarat`;
  }

  const request = { address: query };
  if (fallbackCenter) {
    const lat = typeof fallbackCenter.lat === 'function' ? fallbackCenter.lat() : fallbackCenter.lat;
    const lng = typeof fallbackCenter.lng === 'function' ? fallbackCenter.lng() : fallbackCenter.lng;
    if (lat && lng) {
      request.location = new window.google.maps.LatLng(lat, lng);
    }
  }

  return new Promise((resolve) => {
    geocoder.geocode(request, (results, status) => {
      if (status === 'OK' && results && results[0]) {
        const loc = results[0].geometry.location;
        const pos = { lat: loc.lat(), lng: loc.lng() };
        geocodeCache.set(cacheKey, pos);
        resolve(pos);
      } else {
        geocoder.geocode({ address: cleanLandmark }, (res2, stat2) => {
          if (stat2 === 'OK' && res2 && res2[0]) {
            const loc2 = res2[0].geometry.location;
            const pos2 = { lat: loc2.lat(), lng: loc2.lng() };
            geocodeCache.set(cacheKey, pos2);
            resolve(pos2);
          } else {
            geocodeCache.set(cacheKey, null);
            resolve(null);
          }
        });
      }
    });
  });
}

function doBoxesOverlap(boxA, boxB, padding = 6) {
  return !(
    boxA.right + padding < boxB.left ||
    boxA.left - padding > boxB.right ||
    boxA.bottom + padding < boxB.top ||
    boxA.top - padding > boxB.bottom
  );
}

function createLandmarkOverlay(map, position, titles, count = 1, featureIds = [], onClick) {
  if (!window.google?.maps?.OverlayView) return null;

  class LandmarkOverlayView extends window.google.maps.OverlayView {
    constructor(pos, titlesList, itemCount, featIds) {
      super();
      this.pos = pos;
      this.titles = Array.isArray(titlesList) ? titlesList.map(t => cleanLandmarkTitle(t)) : [cleanLandmarkTitle(titlesList)];
      this.primaryTitle = this.titles[0] || 'Landmark';
      this.count = itemCount || this.titles.length;
      this.featureIds = featIds || [];
      this.container = null;
      this.mode = 'full'; // 'full' | 'compact'
      this.isVisible = true;
      this.isHovered = false;
      this.pixelPos = null;
      this.baseZIndex = 50;
    }

    onAdd() {
      const div = document.createElement('div');
      div.style.position = 'absolute';
      div.style.cursor = 'pointer';
      div.style.transform = 'translate(-50%, -100%)';
      div.style.zIndex = String(this.baseZIndex);
      div.style.pointerEvents = 'auto';
      div.style.transition = 'opacity 0.15s ease';

      div.addEventListener('mouseenter', () => {
        this.isHovered = true;
        div.style.zIndex = '999999';
        this.renderContent(true);
      });

      div.addEventListener('mouseleave', () => {
        this.isHovered = false;
        div.style.zIndex = String(this.baseZIndex);
        this.renderContent(false);
      });

      if (onClick) {
        div.addEventListener('click', (e) => {
          e.stopPropagation();
          onClick();
        });
      }

      this.container = div;
      this.renderContent(false);

      const panes = this.getPanes();
      if (panes?.overlayMouseTarget) {
        panes.overlayMouseTarget.appendChild(div);
      } else if (panes?.overlayLayer) {
        panes.overlayLayer.appendChild(div);
      }
    }

    setMode(newMode) {
      if (this.mode === newMode) return;
      this.mode = newMode;
      this.renderContent(this.isHovered);
    }

    setVisible(visible) {
      this.isVisible = visible;
      if (this.container) {
        this.container.style.display = visible ? 'block' : 'none';
      }
    }

    setBaseZIndex(zIndex) {
      this.baseZIndex = zIndex;
      if (this.container && !this.isHovered) {
        this.container.style.zIndex = String(zIndex);
      }
    }

    renderContent(isExpandedHover = false) {
      if (!this.container) return;

      const extraCount = this.titles.length > 1 ? this.titles.length - 1 : 0;
      const badgeText = this.count > 1 ? `${this.count}` : (extraCount > 0 ? `+${extraCount}` : '');

      let tooltipHtml = '';
      if (isExpandedHover && this.titles.length > 1) {
        tooltipHtml = `
          <div style="
            position: absolute;
            bottom: 100%;
            left: 50%;
            transform: translateX(-50%);
            margin-bottom: 6px;
            background: rgba(15, 23, 42, 0.95);
            border: 1px solid rgba(148, 163, 184, 0.4);
            border-radius: 8px;
