    overflow: 'hidden',
    overflowX: 'hidden',
    transition: 'all 0.25s ease',
    color: isDark ? '#f8fafc' : '#0f172a'
  };

  const headerBg = isDark ? 'rgba(15, 23, 42, 0.95)' : '#f8fafc';
